def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """
    # If the file is already in the file store, we don't need to do anything.
    if existing:
        return

    # If the file is not in the file store, we need to upload it.
    if skip_broken:
        try:
            uploadfunc(fileindex)
        except Exception:
            logger.warning("Skipping broken file %s", fileindex)
            return
    else:
        uploadfunc(fileindex)

