def uploadFileList(uploadfunc, fileindexes, existing, uf, skip_broken=False):
    """Update a list of file objects so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """
    for fileindex in fileindexes:
        uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=skip_broken)


